SELECT V.ID, V.YT_VIDEO_ID, V.TITULO, V.PUBLICADO_EM, V.DURACAO_SEG, V.TIPO, V.THUMB, V.INDISPONIVEL, V.ORIGEM, C.NOME CANAL, X.SCORE, X.NT, X.MOMS FROM (SELECT VIDEO_ID, SUM(P) SCORE, SUM(P = 1) NT, GROUP_CONCAT(M SEPARATOR ',') MOMS FROM (SELECT VT.VIDEO_ID, 10 P, VT.MOMENTOS M FROM VIDEO_TEMAS VT JOIN TEMAS T ON T.ID = VT.TEMA_ID WHERE T.NOME COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{tema}}', '%') UNION ALL SELECT TR.VIDEO_ID, 1 P, CAST(TR.SEGUNDO AS CHAR) M FROM TRECHOS TR WHERE TR.TEXTO COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{tema}}', '%')) U GROUP BY VIDEO_ID) X JOIN VIDEOS V ON V.ID = X.VIDEO_ID AND V.STATUS = 'ESTUDADO' AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) JOIN CANAIS C ON C.ID = V.CANAL_ID ORDER BY CASE WHEN '{{ordem}}' = 'recentes' THEN V.PUBLICADO_EM END DESC, X.SCORE DESC, V.PUBLICADO_EM DESC LIMIT {{limit}} OFFSET {{offset}}